import {useEffect,useRef,useState} from 'react';
import {useInfiniteQuery,useQuery} from '@tanstack/react-query';
import {apiRequest,ApiError} from '../api/client';
import {executeQueueWrite,retryPendingQueueWrite,useQueueCommandLocked} from './queueCommandOwner';
import type {QueueDraftV2,QueuePublishedPlanV2,QueueServiceChoiceV2,QueueWorkflowV2} from '../../../shared/queuePlanV2';
import {QueueWorkflowFields} from './QueueWorkflowFields';
import {workflowDraftIssues,type QueueWorkflowDraft} from './queueWorkflowDraft';
import {PublishedQueuePlans} from './PublishedQueuePlans';
import {OperationButton,OperationQueryState} from './OperationsUi';
import {ConfigurationInput,ConfigurationTextarea} from './ConfigurationUi';
import {TaskDialog} from './TaskDialog';
import {appUrl} from '../surfaces/surfaceConfig';
const base=(tenant:string,location:string)=>`/vendor/tenant/${encodeURIComponent(tenant)}/queue`;
export function WorkflowQueuePanel({token,tenant,location,counterSlug,configurationOnly=false,allowNew=false,onTicketIds,onManagementReady,onConfigured,onEditForm,onClean,onBusy}:{token:string;tenant:string;location:string;counterSlug?:string;configurationOnly?:boolean;allowNew?:boolean;onTicketIds?:(ids:string[],scope:string)=>void;onManagementReady?:(ready:boolean,scope:string)=>void;onConfigured?:()=>void;onEditForm?:(form:HTMLFormElement)=>void;onClean?:(id:string)=>void;onBusy?:(busy:boolean)=>void}){
 const commandLocked=useQueueCommandLocked();
 const scope=`${tenant}:${location}`,url=base(tenant,location),query=`?location=${encodeURIComponent(location)}`;
 const setup=useQuery({queryKey:['workflow-setup',token,scope],queryFn:({signal})=>apiRequest<{workflow:QueueWorkflowV2;counters:Array<{id:string;name:string}>;services:Array<{id:string;name:string}>}>(`${url}/workflow${query}`,{token,signal}),enabled:configurationOnly});
 const catalog=useQuery({queryKey:['workflow-catalog',token,scope],queryFn:({signal})=>apiRequest<{catalogRevision:string;workflow:QueueWorkflowV2;services:QueueServiceChoiceV2[]}>(`${url}/service-options${query}`,{token,signal}),enabled:!configurationOnly});
 const plans=useInfiniteQuery({queryKey:['workflow-plans',token,scope],initialPageParam:undefined as string|undefined,queryFn:({signal,pageParam})=>apiRequest<{plans:QueuePublishedPlanV2[];nextCursor:string|null}>(`${url}/plans${query}&state=active${pageParam?`&cursor=${encodeURIComponent(pageParam)}`:''}`,{token,signal}),getNextPageParam:page=>page.nextCursor||undefined,enabled:!configurationOnly});
 const skipped=useInfiniteQuery({queryKey:['workflow-skipped',token,scope],initialPageParam:undefined as string|undefined,queryFn:({signal,pageParam})=>apiRequest<{plans:QueuePublishedPlanV2[];nextCursor:string|null}>(`${url}/plans${query}&state=skipped${pageParam?`&cursor=${encodeURIComponent(pageParam)}`:''}`,{token,signal}),getNextPageParam:page=>page.nextCursor||undefined,enabled:!configurationOnly});
 const drafts=useInfiniteQuery({queryKey:['workflow-drafts',token,scope],initialPageParam:undefined as string|undefined,queryFn:({signal,pageParam})=>apiRequest<{plans:QueueDraftV2[];nextCursor:string|null}>(`${url}/plans${query}${pageParam?`&cursor=${encodeURIComponent(pageParam)}`:''}`,{token,signal}),getNextPageParam:page=>page.nextCursor||undefined,enabled:!configurationOnly});
 useEffect(()=>{if(!configurationOnly&&plans.hasNextPage&&!plans.isFetchingNextPage&&!plans.isFetchNextPageError)void plans.fetchNextPage();},[configurationOnly,plans.hasNextPage,plans.isFetchingNextPage,plans.isFetchNextPageError,plans.fetchNextPage]);
 useEffect(()=>{if(!configurationOnly&&skipped.hasNextPage&&!skipped.isFetchingNextPage&&!skipped.isFetchNextPageError)void skipped.fetchNextPage();},[configurationOnly,skipped.hasNextPage,skipped.isFetchingNextPage,skipped.isFetchNextPageError,skipped.fetchNextPage]);
 const [trackingPath,setTrackingPath]=useState<string|null>(null);
 const [draft,setDraft]=useState<QueueWorkflowDraft|null>(null),[name,setName]=useState(''),[choices,setChoices]=useState<Record<string,string>>({}),[busy,setBusy]=useState(false),[error,setError]=useState('');
 const draftRevision=useRef<string|null>(null);
 const setupForm=useRef<HTMLFormElement>(null),requestForm=useRef<HTMLFormElement>(null);
 const [reasonAction,setReasonAction]=useState<{plan:QueuePublishedPlanV2;action:'interrupt'|'cancelJourney'|'skip'|'recall'}|null>(null),[reason,setReason]=useState('');
 const busyCallback=useRef(onBusy);busyCallback.current=onBusy;
 const pending=useRef<{path:string;method?:'POST'|'PUT'|'PATCH';body:object;key:string}|null>(null);
 useEffect(()=>{busyCallback.current?.(busy||Boolean(pending.current));},[busy,error]);
 useEffect(()=>()=>busyCallback.current?.(false),[]);
 useEffect(()=>{const reconcile=(event:Event)=>{
  const detail=(event as CustomEvent<{key:string;result?:{workflow?:QueueWorkflowV2;customerAccess?:{path:string};plan?:QueueDraftV2};error?:Error}>).detail;
  if(detail.key!==pending.current?.key)return;
  const command=pending.current;pending.current=null;
  if(event.type==='queue-command-rejected'){setError(detail.error?.message||'The request was rejected. Review and retry.');return;}
  setError('');setReasonAction(null);onClean?.('workflow-reason');
  if(detail.result?.customerAccess)setTrackingPath(detail.result.customerAccess.path);
  if(command?.method==='PUT'&&detail.result?.workflow){const workflow=detail.result.workflow;draftRevision.current=workflow.configurationRevision;setDraft({mode:workflow.mode,stations:structuredClone(workflow.stations),stages:structuredClone(workflow.stages)});onClean?.('workflow-setup');onConfigured?.();}
  if(detail.result?.plan?.state==='draft'){setName('');onClean?.('workflow-request');}
  void plans.refetch();void skipped.refetch();void drafts.refetch();if(configurationOnly)void setup.refetch();
 };window.addEventListener('queue-command-confirmed',reconcile);window.addEventListener('queue-command-rejected',reconcile);return()=>{window.removeEventListener('queue-command-confirmed',reconcile);window.removeEventListener('queue-command-rejected',reconcile);};},[scope,configurationOnly,plans.refetch,drafts.refetch,setup.refetch]);

 const rendered=[...(plans.data?.pages.flatMap(page=>page.plans)||[]),...(skipped.data?.pages.flatMap(page=>page.plans)||[])].filter(plan=>plan.contractVersion===2&&plan.workflow.mode==='multi_station');
 useEffect(()=>{if(setup.data&&!draft){const workflow=setup.data.workflow;draftRevision.current=workflow.configurationRevision;setDraft({mode:workflow.mode,stations:structuredClone(workflow.stations),stages:structuredClone(workflow.stages)});}},[setup.data,draft]);
 useEffect(()=>{onTicketIds?.(rendered.map(plan=>plan.ticketId),scope);onManagementReady?.(plans.isSuccess&&!plans.hasNextPage&&!plans.isFetchingNextPage&&skipped.isSuccess&&!skipped.hasNextPage&&!skipped.isFetchingNextPage,scope);},[scope,plans.data,plans.isSuccess,plans.hasNextPage,plans.isFetchingNextPage,skipped.data,skipped.isSuccess,skipped.hasNextPage,skipped.isFetchingNextPage]);
 useEffect(()=>{if(configurationOnly)return;const refresh=()=>{if(document.visibilityState!=='visible')return;void plans.refetch();void skipped.refetch();void drafts.refetch();void catalog.refetch();};const interval=window.setInterval(refresh,15000);window.addEventListener('queue-plans-updated',refresh);window.addEventListener('focus',refresh);window.addEventListener('online',refresh);return()=>{window.clearInterval(interval);window.removeEventListener('queue-plans-updated',refresh);window.removeEventListener('focus',refresh);window.removeEventListener('online',refresh);};},[configurationOnly,scope,plans.refetch,catalog.refetch]);
 async function write<T>(command:{path:string;method?:'POST'|'PUT'|'PATCH';body:object;key:string}){
  pending.current=command;
  try{const result=await executeQueueWrite<T>({...command,token});pending.current=null;return result;}catch(reason){if(reason instanceof ApiError&&reason.status<500)pending.current=null;throw reason;}
 }
 async function saveSetup(){if(!draft||!setup.data||busy)return;setBusy(true);setError('');try{await write({path:`${url}/workflow${query}`,method:'PUT',body:{mode:draft.mode,stations:draft.stations,stages:draft.stages,expectedConfigurationRevision:draftRevision.current},key:crypto.randomUUID()});const refreshed=await setup.refetch();if(refreshed.data){const workflow=refreshed.data.workflow;draftRevision.current=workflow.configurationRevision;setDraft({mode:workflow.mode,stations:structuredClone(workflow.stations),stages:structuredClone(workflow.stages)});}onClean?.('workflow-setup');onConfigured?.();}catch(reason){setError(reason instanceof Error?reason.message:'The workflow could not be saved.');}finally{setBusy(false);}}
 async function create(){if(busy||!catalog.data)return;setBusy(true);setError('');try{
  const workflow=catalog.data.workflow;const lines=workflow.stages.map(stage=>{const id=choices[stage.stageId]||stage.serviceIds[0];const service=catalog.data!.services.find(value=>value.id===id);return {lineId:crypto.randomUUID(),serviceId:id,quantity:1,durationMinutes:service?.durationMinutes};});
  await write<{plan:QueueDraftV2}>({path:`${url}/plans${query}`,body:{customer:{name},catalogRevision:catalog.data.catalogRevision,lines},key:crypto.randomUUID()});
  setName('');onClean?.('workflow-request');await drafts.refetch();
 }catch(reason){setError(reason instanceof Error?reason.message:'The journey could not be published.');}finally{setBusy(false);}}
 async function action(plan:QueuePublishedPlanV2,action:QueuePublishedPlanV2['allowedActions'][number],confirmedReason?:string){
  if((action==='interrupt'||action==='cancelJourney'||action==='skip'||action==='recall')&&confirmedReason===undefined){setReason('');setReasonAction({plan,action});return;}
  if(busy)return;setBusy(true);setError('');try{const extra:Record<string,unknown>={};
   if(action==='call'){if(!counterSlug)throw new Error('Choose the destination station counter first.');extra.counterSlug=counterSlug;}
   if((action==='start'||action==='skip')&&plan.currentStage.resourceRequirement?.kind!=='none')extra.reservationGroupId=plan.reservationGroups.find(group=>group.state==='protected'&&group.stageAttemptId===plan.currentStage.attemptId)?.id;
   if(action==='complete'){extra.completeAll=true;const group=plan.allocationGroups.find(group=>!group.releasedAt&&group.stageAttemptId===plan.currentStage.attemptId);if(group)extra.allocationGroupId=group.id;}
   if(action==='interrupt'||action==='cancelJourney'||action==='skip'||action==='recall'){if(!confirmedReason?.trim())return;extra.reason=confirmedReason.trim();const group=plan.allocationGroups.find(group=>!group.releasedAt&&group.stageAttemptId===plan.currentStage.attemptId);if(group&&action==='interrupt')extra.allocationGroupId=group.id;}
   if(action==='pause'||action==='resume'){extra.allocationGroupId=plan.allocationGroups.find(group=>!group.releasedAt&&group.stageAttemptId===plan.currentStage.attemptId)?.id;}
   await write({path:`${url}/plans/${encodeURIComponent(plan.id)}/${action}${query}`,body:{expectedTicketRevision:plan.ticketRevision,expectedPlanRevision:plan.planRevision,currentStageId:plan.currentStage.id,expectedStageRevision:plan.currentStage.revision,...extra},key:crypto.randomUUID()});setReasonAction(null);onClean?.('workflow-reason');await plans.refetch();await skipped.refetch();
  }catch(reason){setError(reason instanceof Error?reason.message:'The stage action could not be completed.');}finally{setBusy(false);}
 }
 if(!configurationOnly&&!allowNew&&plans.isSuccess&&!plans.hasNextPage&&skipped.isSuccess&&!skipped.hasNextPage&&drafts.isSuccess&&!rendered.length&&!(drafts.data?.pages.some(page=>page.plans.some(plan=>plan.contractVersion===2)))&&!error)return null;
 return <section className="queue-stack" aria-label={configurationOnly?'Sequential workflow setup':'Workflow journeys'}><h2>{configurationOnly?'Sequential workflow setup':'Workflow journeys'}</h2>{error?<p role="alert">{error}</p>:null}{trackingPath?<a href={appUrl('customer',trackingPath)} target="_blank" rel="noreferrer">Open customer tracking</a>:null}{pending.current?<OperationButton disabled={busy} onClick={async()=>{setBusy(true);try{await retryPendingQueueWrite();pending.current=null;await plans.refetch();await skipped.refetch();await drafts.refetch();if(configurationOnly)await setup.refetch();setError('');}catch(reason){setError(reason instanceof Error?reason.message:'Retry failed.');}finally{setBusy(false);}}}>Retry the same request</OperationButton>:null}
 {configurationOnly?<><OperationQueryState loading={setup.isPending} error={setup.error} onRetry={()=>void setup.refetch()}/>{draft&&setup.data?<form id="workflow-setup" ref={setupForm} onSubmit={event=>event.preventDefault()}><QueueWorkflowFields draft={draft} counters={setup.data.counters} services={setup.data.services} busy={busy||Boolean(pending.current)||commandLocked} onChange={value=>{setDraft(value);if(setupForm.current)onEditForm?.(setupForm.current);}}/><OperationButton disabled={busy||Boolean(pending.current)||workflowDraftIssues(draft,setup.data.counters,setup.data.services).length>0} onClick={()=>void saveSetup()}>Save station workflow</OperationButton><OperationButton variant="outline" disabled={busy||Boolean(pending.current)||commandLocked} onClick={async()=>{const refreshed=await setup.refetch();if(refreshed.data){const workflow=refreshed.data.workflow;draftRevision.current=workflow.configurationRevision;setDraft({mode:workflow.mode,stations:structuredClone(workflow.stations),stages:structuredClone(workflow.stages)});onClean?.('workflow-setup');setError('');}}}>Discard edits and reload saved workflow</OperationButton></form>:null}</>:<><OperationQueryState loading={plans.isPending||skipped.isPending||catalog.isPending} error={plans.error||skipped.error||catalog.error} onRetry={()=>{void plans.refetch();void skipped.refetch();void drafts.refetch();void catalog.refetch();}}/>{allowNew&&catalog.data?.workflow.mode==='multi_station'?<form id="workflow-request" ref={requestForm} onChangeCapture={event=>onEditForm?.(event.currentTarget)} onSubmit={event=>{event.preventDefault();void create();}}><ConfigurationInput label="Customer name for journey" value={name} disabled={busy||Boolean(pending.current)||commandLocked} onChange={event=>setName(event.currentTarget.value)}/>{catalog.data.workflow.stages.map(stage=><label key={stage.stageId}>{stage.label}<select aria-label={`Service for ${stage.label}`} value={choices[stage.stageId]||stage.serviceIds[0]||''} disabled={busy||Boolean(pending.current)||commandLocked} onChange={event=>setChoices({...choices,[stage.stageId]:event.target.value})}>{stage.serviceIds.map(id=><option key={id} value={id}>{catalog.data?.services.find(service=>service.id===id)?.name||'Unavailable service'}</option>)}</select></label>)}<OperationButton type="submit" disabled={busy||Boolean(pending.current)||commandLocked||!name.trim()}>Save workflow request draft</OperationButton></form>:null}{(drafts.data?.pages.flatMap(page=>page.plans)||[]).filter(plan=>plan.contractVersion===2).map(plan=><article key={plan.id}><h3>{plan.customer.name||'Unnamed workflow draft'}</h3><p>{plan.publishReadiness?.blockReasons.map(reason=>reason.message).join(' ')}</p><OperationButton disabled={busy||Boolean(pending.current)||commandLocked||!plan.allowedActions.includes('publish')} onClick={async()=>{setBusy(true);setError('');try{const published=await write<{customerAccess?:{path:string}}>({path:`${url}/plans/${encodeURIComponent(plan.id)}/publish${query}`,body:{expectedPlanRevision:plan.planRevision,expectedCatalogRevision:plan.catalogRevision},key:crypto.randomUUID()});if(published.customerAccess)setTrackingPath(published.customerAccess.path);await drafts.refetch();await plans.refetch();await skipped.refetch();}catch(reason){setError(reason instanceof Error?reason.message:'Publication failed.');}finally{setBusy(false);}}}>Publish workflow request</OperationButton></article>)}{drafts.hasNextPage?<OperationButton disabled={drafts.isFetchingNextPage} onClick={()=>void drafts.fetchNextPage()}>Load more workflow drafts</OperationButton>:null}<PublishedQueuePlans actions={['call','start','complete','interrupt','pause','resume','handoff','ready','arrive','retry','skip','recall','cancelJourney'] as const} plans={rendered} busy={busy||Boolean(pending.current)||commandLocked} onAction={(plan,selected)=>void action(plan,selected)}/>{skipped.hasNextPage?<OperationButton disabled={skipped.isFetchingNextPage} onClick={()=>void skipped.fetchNextPage()}>Load more skipped journeys</OperationButton>:null}{plans.hasNextPage?<OperationButton disabled={plans.isFetchingNextPage} onClick={()=>void plans.fetchNextPage()}>Load more journeys</OperationButton>:null}</>}
 {reasonAction?<TaskDialog opened onClose={()=>{if(busy||pending.current)return;setReasonAction(null);onClean?.('workflow-reason');}} busy={busy||Boolean(pending.current)||commandLocked} title={reasonAction.action==='cancelJourney'?'Cancel future progression?':reasonAction.action==='skip'?'Skip this called stage?':reasonAction.action==='recall'?'Recall this skipped stage?':'Interrupt this stage?'} description={reasonAction.action==='recall'?'Confirm the customer is present. This restores the same station and frozen route; readiness and arrival must be recorded again.':reasonAction.action==='skip'?'Release the unstarted call protection and retain this journey for later recall.':reasonAction.action==='cancelJourney'?'The remaining steps will be cancelled. Any active service keeps its resources until staff records an explicit outcome.':'Record why this stage is being interrupted.'} footer={<><OperationButton variant="outline" disabled={busy||Boolean(pending.current)||commandLocked} onClick={()=>{setReasonAction(null);onClean?.('workflow-reason');}}>Keep working</OperationButton><OperationButton disabled={busy||Boolean(pending.current)||commandLocked||!reason.trim()||reason.length>500} onClick={()=>void action(reasonAction.plan,reasonAction.action,reason)}>Confirm</OperationButton></>}><form id="workflow-reason" onChangeCapture={event=>onEditForm?.(event.currentTarget)} onSubmit={event=>event.preventDefault()}><ConfigurationTextarea label="Reason" value={reason} maxLength={500} disabled={busy||Boolean(pending.current)||commandLocked} onChange={event=>setReason(event.currentTarget.value)}/></form></TaskDialog>:null}
 </section>;
}
